            return [dx, dy]

    for dx, dy in ([0, 0], [1, 0], [0, 1], [-1, 0], [0, -1]):
        nx, ny = sx + dx, sy + dy
        if ok(nx, ny):
            return [dx, dy]

    return [0, 0]

